@JvmName("step270")
fun step270(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 65
}
data class Pair271<A, B>(val first: A, val second: B)

fun combine271(left: Int, right: Int): Pair271<Int, Int> {
    return Pair271(left + 72, right + 26)
}
sealed class Outcome272 {
    data class Success(val payload: String) : Outcome272()
    data object Failure : Outcome272()
}

fun describe272(outcome: Outcome272): String = when (outcome) {
    is Outcome272.Success -> outcome.payload
    Outcome272.Failure -> "failed"
}
